definitions = """
def mat(name, rgb, rough=.88, wood=False):
    m=bpy.data.materials.get(name)
    if m: return m
    m=bpy.data.materials['PierWood_Lit'].copy() if wood else bpy.data.materials.new(name)
    m.name=name
    m.use_nodes=True
    bs=m.node_tree.nodes.get('Principled BSDF')
    bs.inputs['Base Color'].default_value=(*rgb,1)
    bs.inputs['Roughness'].default_value=rough
    bs.inputs['Metallic'].default_value=0
    if 'Specular IOR Level' in bs.inputs: bs.inputs['Specular IOR Level'].default_value=.22
    if wood:
        for n in m.node_tree.nodes:
            if n.type=='TEX_IMAGE' and n.image and 'Albedo' in n.image.name:
                mix=m.node_tree.nodes.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY'
                mix.inputs[0].default_value=1;mix.inputs[2].default_value=(*rgb,1)
                m.node_tree.links.new(n.outputs['Color'],mix.inputs[1])
                m.node_tree.links.new(mix.outputs[0],bs.inputs['Base Color'])
    return m
wood=mat('Coast seasoned timber',(.60,.48,.33),wood=True)
trim=mat('Coast dark structural wood',(.32,.30,.24),wood=True)
pale=mat('Coast pale joinery',(.89,.83,.66),wood=True)
roof=[mat('Coast warm shingle '+str(i),c,wood=True) for i,c in enumerate([(.54,.39,.27),(.61,.46,.32),(.49,.37,.28),(.66,.49,.34)])]
stone=mat('Coast foundation stone',(.39,.43,.38))
glass=mat('Coast shaded blue glass',(.12,.27,.29),.45)
