ochre=mat('Coast ochre plaster',(.64,.48,.30))
red=mat('Coast faded terracotta',(.53,.26,.17))
def group(name):
    c=bpy.data.collections.new(name);bpy.context.scene.collection.children.link(c);return c
def move(o,c,name,material):
    o.name=name
    for old in list(o.users_collection):old.objects.unlink(o)
    c.objects.link(o)
    if material:o.data.materials.append(material)
    return o
def box(c,name,p,s,m,bevel=.025):
    bpy.ops.mesh.primitive_cube_add(size=1,location=(p[0],-p[2],p[1]))
    o=bpy.context.object;o.scale=(s[0],s[2],s[1])
    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
    if bevel:
        mod=o.modifiers.new('Soft worn edges','BEVEL');mod.width=bevel;mod.segments=2
        bpy.ops.object.modifier_apply(modifier=mod.name)
    for poly in o.data.polygons:
        n=poly.normal;axis=max(range(3),key=lambda i:abs(n[i]))
        axes=[i for i in range(3) if i!=axis]
        for li in poly.loop_indices:
            v=o.data.vertices[o.data.loops[li].vertex_index].co
            o.data.uv_layers.active.data[li].uv=(v[axes[0]]*.48,v[axes[1]]*.48)
    return move(o,c,name,m)
def cylinder(c,name,p,r,depth,m,vertices=12):
    bpy.ops.mesh.primitive_cylinder_add(vertices=vertices,radius=r,depth=depth,location=(p[0],-p[2],p[1]))
    return move(bpy.context.object,c,name,m)
def beam(c,name,a,b,width,m):
    av=Vector((a[0],-a[2],a[1]));bv=Vector((b[0],-b[2],b[1]))
    o=box(c,name,(0,0,0),(width,(bv-av).length,width),m,.015)
    o.location=(av+bv)*.5;o.rotation_euler=(bv-av).to_track_quat('Z','Y').to_euler()
    return o
def roof_gable(c,depth,width,eave,rise,material=None,prefix='Roof'):
    dx=depth*.5+.42;zz=width*.5+.5
    slope=math.atan2(rise,dx)
    for side in [-1,1]:
        plane=box(c,prefix+' underlay',(side*dx*.5,eave+rise*.5,0),(math.hypot(dx,rise),.12,zz*2),trim,.02)
        plane.rotation_euler.y=side*slope
        rows=8;cols=max(5,round(zz*2/.45))
        for row in range(rows):
            x=(row+.48)*dx/rows
            for col in range(cols):
                z=-zz+(col+.5)*(zz*2/cols)+(0.04 if row%2 else -.04)
                tile=box(c,prefix+' shingle',(side*x,eave+rise*(1-x/dx)+.10,z),(math.hypot(dx,rise)/rows+.12,.075,zz*2/cols-.018),material or roof[(row+col*3)%4],.012)
                tile.rotation_euler.y=side*slope
        for z in [-zz,zz]:
            beam(c,prefix+' gable fascia',(side*dx,eave-.08,z),(0,eave+rise-.08,z),.17,pale)
    beam(c,prefix+' ridge cap',(0,eave+rise+.16,-zz-.06),(0,eave+rise+.16,zz+.06),.19,trim)
def window(c,x,y,z,width=1.1,height=1.25,side=False):
    # Window opening and shutters on the sea-facing wall; same recess around sides.
    if not side:
        box(c,'Window dark recess',(x,y,z),(.055,height,width),glass,.008)
        for dz in [-width*.5,width*.5]:
            box(c,'Window frame',(x-.07,y,z+dz),(.13,height+.18,.10),pale,.012)
        for dy in [-height*.5,height*.5]:
            box(c,'Window lintel',(x-.08,y+dy,z),(.17,.10,width+.2),pale,.012)
        box(c,'Window mullion',(x-.09,y,z),(.12,height,.055),pale,.008)
        for side_ in [-1,1]:
            shutter=box(c,'Open timber shutter',(x-.24,y,z+side_*(width*.5+.23)),(.07,height,.38),wood,.018)
            shutter.rotation_euler.z=side_*.35
    else:
        box(c,'Side window recess',(x,y,z),(width,height,.06),glass,.008)
        for dx in [-width*.5,width*.5]:
            box(c,'Side frame',(x+dx,y,z),( .10,height+.18,.14),pale,.012)
        for dy in [-height*.5,height*.5]:
            box(c,'Side lintel',(x,y+dy,z),(width+.2,.10,.17),pale,.012)
        box(c,'Side mullion',(x,y,z),(.07,height,.15),pale,.008)
def building(name,depth,width,eave,rise,wall,porch=True):
    c=group(name)
    box(c,'Stone plinth',(0,.12,0),(depth+.3,.55,width+.3),stone,.07)
    box(c,'Wall body',(0,(eave+.4)*.5,0),(depth,eave-.4,width),wall,.04)
    for x in [-depth*.5,depth*.5]:
        for z in [-width*.5,width*.5]:
            box(c,'Corner timber',(x,(eave+.4)*.5,z),(.18,eave-.3,.18),trim)
    for y in [.43,eave-.05]:
        box(c,'Front horizontal beam',(-depth*.5-.03,y,0),(.20,.18,width+.25),wood)
        box(c,'Rear horizontal beam',(depth*.5+.03,y,0),(.20,.18,width+.25),wood)
    # Gable end infill uses a triangular prism, authored in Blender.
    for z in [-width*.5,width*.5]:
        verts=[(-depth*.5,-z,eave),(depth*.5,-z,eave),(0,-z,eave+rise-.1),(-depth*.5,-z+.10,eave),(depth*.5,-z+.10,eave),(0,-z+.10,eave+rise-.1)]
        mesh=bpy.data.meshes.new('Gable timber mesh');mesh.from_pydata(verts,[],[(0,2,1),(3,4,5),(0,1,4,3),(1,2,5,4),(2,0,3,5)]);mesh.update()
        o=bpy.data.objects.new('Gable infill',mesh);c.objects.link(o);o.data.materials.append(wood)
        beam(c,'Gable centre beam',(0,eave,z),(0,eave+rise,z),.15,trim)
    roof_gable(c,depth,width,eave,rise)
    # Seaward entrance, two flanking windows and finished side/rear openings.
    doorx=-depth*.5-.07
    box(c,'Door recess',(doorx,1.4,0),(.08,2,1.02),trim)
    for i in range(6):box(c,'Door plank',(doorx-.06,1.4,(i-2.5)*.145),(.055,1.91,.135),wood,.01)
    for z in [-.56,.56]:box(c,'Door jamb',(doorx-.10,1.43,z),(.17,2.14,.14),pale)
    box(c,'Door lintel',(doorx-.10,2.52,0),(.18,.14,1.26),pale)
    cylinder(c,'Door latch',(doorx-.16,1.35,-.31),.045,.12,iron)
    for z in [-width*.32,width*.32]:window(c,doorx,1.95,z,min(1.05,width*.21),1.1)
    for z in [-width*.5-.03,width*.5+.03]:window(c,0,1.95,z,1.3,1.15,True)
    window(c,depth*.5+.05,1.95,0,1.3,1.1)
    if porch:
        for i in range(14):box(c,'Veranda board',(-depth*.5-.77,.36,(i-6.5)*width/14),(1.65,.12,width/14-.015),wood,.012)
        for z in [-width*.5+.15,width*.5-.15]:
            box(c,'Veranda post',(-depth*.5-1.38,1.55,z),(.18,2.5,.18),trim)
            beam(c,'Porch brace',(-depth*.5-1.38,2.0,z),(-depth*.5-.65,2.65,z),.13,wood)
        canopy=box(c,'Porch canopy',(-depth*.5-.75,2.8,0),(1.85,.16,width+.55),wood,.04)
        canopy.rotation_euler.y=-.10
        for i in range(3):box(c,'Entrance step',(-depth*.5-1.5-i*.29,.25-i*.09,0),(.4,.14,1.65),stone,.035)
    return c
def finish(c):
    bpy.ops.object.select_all(action='DESELECT')
    bymat={}
    for o in list(c.objects):
        if o.type=='MESH':
            key=o.data.materials[0].name if o.data.materials else ''
            bymat.setdefault(key,[]).append(o)
    for name,objects in bymat.items():
        for o in objects:o.select_set(True)
        bpy.context.view_layer.objects.active=objects[0]
        if len(objects)>1:bpy.ops.object.join()
        bpy.context.object.name=c.name+' '+name
        bpy.ops.object.select_all(action='DESELECT')
    print(c.name,len(c.objects),'materials',len(bymat))
